-- ============================================
-- LUMA — Scénarios jouables : Thématique 1 (Restaurant), lot 2 — formats longs
-- ============================================

update scenarios set content = '{"characters": {"host": "M. Reynolds (client potentiel)"}, "start_node": "n1", "nodes": {"n1": {"speaker": "host", "text": "Thank you for joining me tonight. Shall we start with drinks?", "text_fr": "Merci de m''avoir rejoint ce soir. On commence par les boissons ?", "choices": [{"text": "That sounds great, I''ll have a sparkling water.", "next": "n2"}, {"text": "I''d love a glass of red wine, thank you.", "next": "n2"}]}, "n2": {"speaker": "host", "text": "Good choice. So, tell me about your company''s plans for next year.", "text_fr": "Bon choix. Alors, parlez-moi des projets de votre entreprise pour l''année prochaine.", "choices": [{"text": "We''re planning to expand into three new markets.", "next": "n3"}, {"text": "I''d rather hear about your priorities first, if that''s alright.", "next": "n3b"}]}, "n3": {"speaker": "host", "text": "Ambitious! What''s driving that decision?", "text_fr": "Ambitieux ! Qu''est-ce qui motive cette décision ?", "choices": [{"text": "Strong demand and a solid financial position.", "next": "n4"}]}, "n3b": {"speaker": "host", "text": "Fair enough. Honestly, we''re looking for a reliable long-term partner.", "text_fr": "Entendu. Honnêtement, on cherche un partenaire fiable sur le long terme.", "choices": [{"text": "That aligns well with what we''re looking for too.", "next": "n4"}]}, "n4": {"speaker": "host", "text": "I like that. Shall we order? I recommend the sea bass.", "text_fr": "J''aime ça. On commande ? Je recommande le bar de mer.", "choices": [{"text": "I''ll trust your recommendation, thank you.", "next": "n5"}, {"text": "I think I''ll go with the steak, if that''s fine.", "next": "n5"}]}, "n5": {"speaker": "host", "text": "Good choice. Now, about pricing — what flexibility do you have?", "text_fr": "Bon choix. Maintenant, côté tarifs — quelle flexibilité avez-vous ?", "choices": [{"text": "We can discuss volume discounts for a multi-year deal.", "next": "n6"}, {"text": "Let''s finalize the partnership first, then discuss numbers.", "next": "n6b"}]}, "n6": {"speaker": "host", "text": "That''s exactly the kind of flexibility we need.", "text_fr": "C''est exactement la flexibilité dont on a besoin.", "choices": [{"text": "Great, I''ll have our team send a proposal this week.", "next": "end_deal"}]}, "n6b": {"speaker": "host", "text": "I appreciate that approach. Let''s stay in touch.", "text_fr": "J''apprécie cette approche. Restons en contact.", "choices": [{"text": "Absolutely, I''ll follow up next week.", "next": "end_followup"}]}, "end_deal": {"speaker": "host", "text": "Looking forward to it. This could be the start of something great.", "text_fr": "J''ai hâte. Ça pourrait être le début de quelque chose de formidable.", "end": true, "ending_label": "Partenariat en bonne voie 🤝"}, "end_followup": {"speaker": "host", "text": "Sounds good. Thank you for a great evening.", "text_fr": "Parfait. Merci pour cette excellente soirée.", "end": true, "ending_label": "Relation entretenue 👔"}}}'::jsonb, is_playable = true
where title = 'Un dîner d''affaires à enjeux'
  and theme_id = (select id from scenario_themes where position = 1 and language_id = (select id from languages where code = 'en'));

update scenarios set content = '{"characters": {"waiter": "le serveur", "friend": "ton ami Sam"}, "start_node": "n1", "nodes": {"n1": {"speaker": "friend", "text": "I''m so sorry, I think I just knocked over your glass!", "text_fr": "Je suis désolé, je crois que je viens de renverser ton verre !", "choices": [{"text": "Don''t worry, it happens! Let''s ask for a napkin.", "next": "n2"}, {"text": "Oh no, my phone got wet too!", "next": "n2b"}]}, "n2": {"speaker": "waiter", "text": "No worries at all, let me clean this up quickly.", "text_fr": "Aucun souci, je nettoie ça tout de suite.", "choices": [{"text": "Thank you, we appreciate it.", "next": "n3"}]}, "n2b": {"speaker": "waiter", "text": "I''m so sorry! Let me bring some towels right away.", "text_fr": "Je suis vraiment désolé ! J''apporte des serviettes tout de suite.", "choices": [{"text": "Thanks, hopefully it still works.", "next": "n3"}]}, "n3": {"speaker": "waiter", "text": "Would you like a replacement drink, on the house?", "text_fr": "Vous voulez une boisson de remplacement, offerte par la maison ?", "choices": [{"text": "That''s very kind, yes please.", "next": "n4"}, {"text": "That''s not necessary, but thank you.", "next": "n4b"}]}, "n4": {"speaker": "friend", "text": "See, it turned out fine in the end!", "text_fr": "Tu vois, finalement tout s''est bien passé !", "choices": [{"text": "Yeah, and free drinks too!", "next": "end_positive"}]}, "n4b": {"speaker": "friend", "text": "You''re very understanding, thanks for not making a big deal of it.", "text_fr": "Tu es très compréhensif, merci de ne pas en avoir fait tout un plat.", "choices": [{"text": "No worries, these things happen!", "next": "end_positive"}]}, "end_positive": {"speaker": "waiter", "text": "Thank you both for being so kind about it. Enjoy the rest of your evening!", "text_fr": "Merci à vous deux d''être aussi compréhensifs. Bonne fin de soirée !", "end": true, "ending_label": "Incident géré avec le sourire 😊"}}}'::jsonb, is_playable = true
where title = 'Une soirée qui tourne mal'
  and theme_id = (select id from scenario_themes where position = 1 and language_id = (select id from languages where code = 'en'));

update scenarios set content = '{"characters": {"partner": "ton/ta partenaire", "waiter": "le serveur"}, "start_node": "n1", "nodes": {"n1": {"speaker": "partner", "text": "This restaurant is beautiful, I can''t believe you planned all this.", "text_fr": "Ce restaurant est magnifique, je n''arrive pas à croire que tu aies tout organisé.", "choices": [{"text": "I wanted tonight to be really special.", "next": "n2"}, {"text": "I have something important to ask you tonight.", "next": "n2b"}]}, "n2": {"speaker": "waiter", "text": "Good evening, would you like to start with some champagne?", "text_fr": "Bonsoir, vous souhaitez commencer par du champagne ?", "choices": [{"text": "Yes, please, we''re celebrating something special.", "next": "n3"}]}, "n2b": {"speaker": "partner", "text": "You''re making me nervous, in a good way!", "text_fr": "Tu me rends nerveux/nerveuse, mais dans le bon sens !", "choices": [{"text": "Just wait until dessert.", "next": "n3"}]}, "n3": {"speaker": "waiter", "text": "Wonderful, I''ll bring a bottle right away.", "text_fr": "Merveilleux, j''apporte une bouteille tout de suite.", "choices": [{"text": "Thank you so much.", "next": "n4"}]}, "n4": {"speaker": "partner", "text": "Okay, now I''m really curious what you''re planning.", "text_fr": "Bon, maintenant je suis vraiment curieux/curieuse de savoir ce que tu prépares.", "choices": [{"text": "(Take out the ring) Will you marry me?", "next": "n5"}]}, "n5": {"speaker": "partner", "text": "Yes! Yes, of course!", "text_fr": "Oui ! Oui, bien sûr !", "choices": [{"text": "You''ve just made me the happiest person alive.", "next": "end_yes"}]}, "end_yes": {"speaker": "waiter", "text": "Congratulations to you both! The champagne is on us tonight.", "text_fr": "Félicitations à vous deux ! Le champagne est offert ce soir.", "end": true, "ending_label": "Elle/il a dit oui ! 💍"}}}'::jsonb, is_playable = true
where title = 'Un repas de fiançailles'
  and theme_id = (select id from scenario_themes where position = 1 and language_id = (select id from languages where code = 'en'));
